using Microsoft.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public class TicketModelService
{
    private readonly MLContext _mlContext;
    private readonly ILogger<TicketModelService> _logger;
    private ITransformer? _model;
    private string[] _categoryLabels = [];

    public TicketModelService(ILogger<TicketModelService> logger)
    {
        _mlContext = new MLContext(seed: 42);
        _logger = logger;
    }

    public TrainingMetrics TrainModel(string dataPath)
    {
        var data = _mlContext.Data.LoadFromTextFile<TicketInput>(
            dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        var split = _mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);

        var pipeline = _mlContext.Transforms.Conversion.MapValueToKey("Label", nameof(TicketInput.Category))
            .Append(_mlContext.Transforms.Text.FeaturizeText("SubjectFeatures", nameof(TicketInput.Subject)))
            .Append(_mlContext.Transforms.Text.FeaturizeText("DescriptionFeatures", nameof(TicketInput.Description)))
            .Append(_mlContext.Transforms.Concatenate("Features", "SubjectFeatures", "DescriptionFeatures", nameof(TicketInput.Priority)))
            .Append(_mlContext.Transforms.NormalizeMinMax("Features"))
            .Append(_mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy("Label", "Features"))
            .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        _model = pipeline.Fit(split.TrainSet);

        // Extract category labels
        var labelColumn = split.TrainSet.Schema["Label"];
        var labelBuffer = new VBuffer<ReadOnlyMemory<char>>();
        labelColumn.GetKeyValues(ref labelBuffer);
        _categoryLabels = labelBuffer.DenseValues().Select(v => v.ToString()).ToArray();

        // Evaluate on test set
        var predictions = _model.Transform(split.TestSet);
        var metrics = _mlContext.MulticlassClassification.Evaluate(predictions, "Label");

        var result = new TrainingMetrics
        {
            MicroAccuracy = metrics.MicroAccuracy,
            MacroAccuracy = metrics.MacroAccuracy,
            LogLoss = metrics.LogLoss,
            Categories = _categoryLabels
        };

        _logger.LogInformation(
            "Model trained — MicroAccuracy: {Micro:F4}, MacroAccuracy: {Macro:F4}, LogLoss: {LogLoss:F4}",
            result.MicroAccuracy, result.MacroAccuracy, result.LogLoss);

        return result;
    }

    public PredictionEngine<TicketInput, TicketPrediction> CreatePredictionEngine()
    {
        if (_model is null)
            throw new InvalidOperationException("Model has not been trained. Call TrainModel first.");

        return _mlContext.Model.CreatePredictionEngine<TicketInput, TicketPrediction>(_model);
    }

    public string[] GetCategoryLabels() => _categoryLabels;
}

public class TrainingMetrics
{
    public double MicroAccuracy { get; set; }
    public double MacroAccuracy { get; set; }
    public double LogLoss { get; set; }
    public string[] Categories { get; set; } = [];
}

