using Microsoft.Extensions.ML;
using Microsoft.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();
builder.Services.AddSingleton<TicketModelService>();

// Train model at startup
var dataPath = Path.Combine(Directory.GetCurrentDirectory(), "Data", "tickets.csv");
var modelPath = Path.Combine(Directory.GetCurrentDirectory(), "Data", "model.zip");

using (var loggerFactory = LoggerFactory.Create(b => b.AddConsole()))
{
    var service = new TicketModelService(loggerFactory.CreateLogger<TicketModelService>());
    var metrics = service.TrainAndSaveModel(dataPath, modelPath);

    Console.WriteLine("=== Model Training Metrics ===");
    Console.WriteLine($"  Micro Accuracy:     {metrics.MicroAccuracy:P2}");
    Console.WriteLine($"  Macro Accuracy:     {metrics.MacroAccuracy:P2}");
    Console.WriteLine($"  Log Loss:           {metrics.LogLoss:F4}");
    Console.WriteLine($"  Log Loss Reduction: {metrics.LogLossReduction:F4}");
    Console.WriteLine("==============================");
}

// Register prediction engine pool (thread-safe for ASP.NET Core)
builder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>()
    .FromFile(modelPath);

var app = builder.Build();
app.MapControllers();
app.Run();

