using Microsoft.Extensions.ML;
using Microsoft.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();
builder.Services.AddSingleton<TicketModelService>();

// Train model and save to disk before configuring DI
var dataPath = Path.Combine(Directory.GetCurrentDirectory(), "Data", "tickets.csv");
var modelPath = Path.Combine(Directory.GetCurrentDirectory(), "Data", "model.zip");

var mlContext = new MLContext(seed: 42);
var data = mlContext.Data.LoadFromTextFile<TicketInput>(
    dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);

var pipeline = mlContext.Transforms.Conversion.MapValueToKey("Label", nameof(TicketInput.Category))
    .Append(mlContext.Transforms.Text.FeaturizeText("SubjectFeatures", nameof(TicketInput.Subject)))
    .Append(mlContext.Transforms.Text.FeaturizeText("DescriptionFeatures", nameof(TicketInput.Description)))
    .Append(mlContext.Transforms.Concatenate("Features", "SubjectFeatures", "DescriptionFeatures", nameof(TicketInput.Priority)))
    .Append(mlContext.Transforms.NormalizeMinMax("Features"))
    .Append(mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy("Label", "Features"))
    .Append(mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

var model = pipeline.Fit(split.TrainSet);

// Evaluate on test set
var predictions = model.Transform(split.TestSet);
var metrics = mlContext.MulticlassClassification.Evaluate(predictions, "Label");

Console.WriteLine("=== Model Training Metrics ===");
Console.WriteLine($"  Micro Accuracy: {metrics.MicroAccuracy:P2}");
Console.WriteLine($"  Macro Accuracy: {metrics.MacroAccuracy:P2}");
Console.WriteLine($"  Log Loss:       {metrics.LogLoss:F4}");
Console.WriteLine($"  Log Loss Reduction: {metrics.LogLossReduction:F4}");
Console.WriteLine("==============================");

// Save model
mlContext.Model.Save(model, data.Schema, modelPath);

// Register prediction engine pool with the saved model
builder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>()
    .FromFile(modelPath);

var app = builder.Build();
app.MapControllers();
app.Run();

